import { afterEach,describe,expect,it,vi } from 'vitest';
import { NotesController } from '../src/controller.ts';
import { emptyNoteDocument,noteContentKey } from '@linuxcast/contracts';
import type { NoteRecord,NoteWrite,NotesApi } from '@linuxcast/contracts';
const id='11111111-1111-4111-8111-111111111111',other='22222222-2222-4222-8222-222222222222',time='2026-10-29T00:00:00.000Z';
const content=(title='Public note')=>({title,document:emptyNoteDocument()});
function fixture(){let record:NoteRecord={id,revision:1,documentVersion:1,archived:false,trashed:false,pinned:false,draft:content(),saved:content(),createdAt:time,updatedAt:time};const inputs:NoteWrite[]=[];
 const api:NotesApi={list:vi.fn<NotesApi['list']>(async({query})=>({ok:true,value:{query,records:[{id,revision:record.revision,title:record.draft.title,pinned:record.pinned,archived:record.archived,trashed:record.trashed,excerpt:'',hasDraft:noteContentKey(record.draft)!==noteContentKey(record.saved!),updatedAt:time}],nextCursor:null}})),get:vi.fn<NotesApi['get']>(async()=>({ok:true,value:structuredClone(record)})),write:vi.fn<NotesApi['write']>(async input=>{inputs.push(structuredClone(input));record={...record,pinned:record.id===input.id?record.pinned:false,archived:record.id===input.id?record.archived:false,trashed:record.id===input.id?record.trashed:false,id:input.id,revision:input.expectedRevision+1,draft:structuredClone(input.content),saved:input.action==='save'?structuredClone(input.content):record.id===input.id?record.saved:null};return{ok:true,value:structuredClone(record)};}),close:vi.fn(async()=>{}),getAppearance:async()=>'dark',onAppearance:()=>()=>{},onCloseRequested:()=>()=>{}};
 const controller=new NotesController(api);return{api,controller,inputs,get record(){return record;}};
}
const controllers:NotesController[]=[];afterEach(()=>{controllers.splice(0).forEach(controller=>controller.dispose());vi.useRealTimers();});
async function ready(){const f=fixture();controllers.push(f.controller);await f.controller.select(id);return f;}
const tick=async()=>{await Promise.resolve();await Promise.resolve();};
describe('Notes draft and saved lifecycle',()=>{
 it('loads exact record without a write',async()=>{const{controller,api}=await ready();expect(controller.snapshot.content?.title).toBe('Public note');expect(api.write).not.toHaveBeenCalled();});
 it('debounces 500ms and preserves saved version',async()=>{const{controller,inputs}=await ready();vi.useFakeTimers();controller.editTitle('Newest');await vi.advanceTimersByTimeAsync(499);expect(inputs).toHaveLength(0);await vi.advanceTimersByTimeAsync(1);expect(inputs).toHaveLength(1);expect(inputs[0]?.action).toBe('draft');expect(controller.snapshot.record?.saved?.title).toBe('Public note');});
 it('explicit Save writes latest content as saved, with no prior draft needed',async()=>{const{controller,inputs}=await ready();controller.editTitle('Explicit');expect(await controller.save()).toBe(true);expect(inputs.map(value=>value.action)).toEqual(['save']);expect(controller.unsaved).toBe(false);});
 it('New uses one UUID and expected0 draft with no implicit Save',async()=>{const{controller,api}=fixture();controllers.push(controller);await controller.newNote();expect(api.write).toHaveBeenCalledWith(expect.objectContaining({expectedRevision:0,action:'draft',content:content('Untitled note')}));expect(controller.snapshot.blocked).toBe(false);expect(controller.snapshot.record?.saved).toBeNull();});
 it('serializes typing during write without replacing newer local content',async()=>{const{controller,api}=await ready();const real=api.write;let release!:(value:Awaited<ReturnType<NotesApi['write']>>)=>void;vi.mocked(api.write).mockImplementationOnce(()=>new Promise(resolve=>{release=resolve;}));controller.editTitle('First');const flushing=controller.flush();await tick();controller.editTitle('Second');release({ok:true,value:{id,revision:2,documentVersion:1,archived:false,trashed:false,pinned:false,draft:content('First'),saved:content(),createdAt:time,updatedAt:time}});await flushing;expect(controller.snapshot.content?.title).toBe('Second');expect(vi.mocked(real).mock.calls).toHaveLength(2);expect(controller.snapshot.record?.revision).toBe(3);});
 it('duplicate Save shares a single request',async()=>{const{controller,api}=await ready();controller.editTitle('Next');const a=controller.save(),b=controller.save();expect(a).toBe(b);await a;expect(api.write).toHaveBeenCalledTimes(1);});
 it('invalid local title never enters write API',async()=>{const{controller,api}=await ready();controller.editTitle(' ');expect(await controller.flush()).toBe(false);expect(api.write).not.toHaveBeenCalled();expect(controller.snapshot.error).toContain('nonblank');});
 for(const code of ['conflict','internal'])it(`${code} requires confirmed reconciliation and never replays`,async()=>{const{controller,api}=await ready();vi.mocked(api.write).mockResolvedValue({ok:false,error:{code:code as 'internal',message:'PRIVATE',retryable:false}});controller.editTitle('Local kept');await controller.save();expect(controller.snapshot.blocked).toBe(true);expect(controller.snapshot.error).not.toContain('PRIVATE');controller.confirmReload();await controller.reconcile();expect(controller.snapshot.content?.title).toBe('Local kept');expect(controller.snapshot.blocked).toBe(false);expect(api.write).toHaveBeenCalledTimes(1);});
 it('known unavailable permits only deliberate retry and keeps local content',async()=>{const{controller,api}=await ready();vi.mocked(api.write).mockResolvedValueOnce({ok:false,error:{code:'capability-unavailable',message:'PRIVATE',retryable:false}});controller.editTitle('Retry me');await controller.save();expect(controller.snapshot.blocked).toBe(false);expect(controller.snapshot.paused).toBe(true);expect(await controller.retry()).toBe(true);expect(api.write).toHaveBeenCalledTimes(2);});
 for(const fault of ['id','revision','draft','saved','extra'])it(`rejects ${fault} mismatched acknowledgement`,async()=>{const{controller,api}=await ready();vi.mocked(api.write).mockImplementationOnce(async input=>({ok:true,value:{id:fault==='id'?other:id,revision:fault==='revision'?9:2,documentVersion:1,archived:false,trashed:false,pinned:false,draft:fault==='draft'?content('Wrong'):input.content,saved:fault==='saved'?content('Wrong'):input.content,createdAt:time,updatedAt:time,...(fault==='extra'?{extra:true}:{})}}));controller.editTitle('Save this');expect(await controller.save()).toBe(false);expect(controller.snapshot.blocked).toBe(true);});
 it('draft acknowledgement cannot mutate saved version',async()=>{const{controller,api}=await ready();vi.mocked(api.write).mockImplementationOnce(async input=>({ok:true,value:{id,revision:2,documentVersion:1,archived:false,trashed:false,pinned:false,draft:input.content,saved:input.content,createdAt:time,updatedAt:time}}));controller.editTitle('Draft');await controller.flush();expect(controller.snapshot.blocked).toBe(true);});
 it('receipt comparison ignores object key order',async()=>{const{controller,api}=await ready();vi.mocked(api.write).mockImplementationOnce(async input=>({ok:true,value:{id,revision:2,documentVersion:1,archived:false,trashed:false,pinned:false,draft:{document:input.content.document,title:input.content.title},saved:{document:input.content.document,title:input.content.title},createdAt:time,updatedAt:time}}));controller.editTitle('Ordered');expect(await controller.save()).toBe(true);});
 it('timeout blocks and late acknowledgement does not confirm or replay',async()=>{const{controller,api}=await ready();vi.useFakeTimers();let release!:(value:Awaited<ReturnType<NotesApi['write']>>)=>void;vi.mocked(api.write).mockImplementationOnce(()=>new Promise(resolve=>{release=resolve;}));controller.editTitle('Late');const saving=controller.save();await vi.advanceTimersByTimeAsync(5001);expect(await saving).toBe(false);release({ok:true,value:{id,revision:2,documentVersion:1,archived:false,trashed:false,pinned:false,draft:content('Late'),saved:content('Late'),createdAt:time,updatedAt:time}});await tick();expect(controller.snapshot.blocked).toBe(true);expect(controller.snapshot.record?.revision).toBe(1);});
 it('flushes before selection and refuses navigation on uncertainty',async()=>{const{controller,api}=await ready();vi.mocked(api.write).mockRejectedValueOnce(new Error('private'));controller.editTitle('Keep');await controller.select(other);expect(api.get).toHaveBeenCalledTimes(1);expect(controller.snapshot.id).toBe(id);});
 it('failed close exposes choices and explicit close never replays a write',async()=>{const{controller,api}=await ready();vi.mocked(api.write).mockRejectedValueOnce(new Error('private'));controller.editTitle('Keep');expect(await controller.requestClose()).toBe(false);expect(controller.snapshot.closeFailed).toBe(true);expect(api.close).not.toHaveBeenCalled();expect(await controller.closeWithoutFlush()).toBe(true);expect(api.write).toHaveBeenCalledTimes(1);});
 it('successful native close flush returns true after API close',async()=>{const{controller,api}=await ready();controller.editTitle('Before close');expect(await controller.requestClose()).toBe(true);expect(api.write).toHaveBeenCalledTimes(1);expect(api.close).toHaveBeenCalledTimes(1);});
 it('disposal during pending publication fences dispatch and new work',async()=>{const{controller,api}=await ready();controller.editTitle('No dispatch');controller.subscribe(()=>{if(controller.snapshot.busy){controller.dispose();void controller.newNote();void controller.save();}});expect(await controller.save()).toBe(false);expect(api.write).not.toHaveBeenCalled();});
 it('disposal ignores pending completion without changing local content',async()=>{const{controller,api}=await ready();let release!:(value:Awaited<ReturnType<NotesApi['write']>>)=>void;vi.mocked(api.write).mockImplementationOnce(()=>new Promise(resolve=>{release=resolve;}));controller.editTitle('Local');const save=controller.save();controller.dispose();release({ok:true,value:{id,revision:2,documentVersion:1,archived:false,trashed:false,pinned:false,draft:content('Local'),saved:content('Local'),createdAt:time,updatedAt:time}});expect(await save).toBe(false);expect(controller.snapshot.record?.revision).toBe(1);});
 it('search rejects wrong echo and oversized queries without leaking owner errors',async()=>{const{controller,api}=await ready();vi.mocked(api.list).mockResolvedValueOnce({ok:true,value:{query:'wrong',records:[],nextCursor:null}});await controller.reloadList();expect(controller.snapshot.listError).toContain('could not');controller.setQuery('x'.repeat(257));await controller.reloadList();expect(api.list).toHaveBeenCalledTimes(1);});
 it('stale query results cannot replace newer query results',async()=>{const{controller,api}=await ready();let release!:(value:Awaited<ReturnType<NotesApi['list']>>)=>void;vi.mocked(api.list).mockImplementationOnce(()=>new Promise(resolve=>{release=resolve;}));const old=controller.reloadList();controller.setQuery('new');await controller.reloadList();release({ok:true,value:{query:'',records:[],nextCursor:null}});await old;expect(controller.snapshot.rows).toHaveLength(1);expect(controller.snapshot.query).toBe('new');});
 it('mismatched record get cannot replace selection',async()=>{const{controller,api}=await ready();vi.mocked(api.get).mockResolvedValueOnce({ok:true,value:{...controller.snapshot.record!,id}});await controller.select(other);expect(controller.snapshot.id).toBe(id);expect(controller.snapshot.error).toContain('unavailable');});
});
it('freezes previous note during a pending selection so local edits cannot be silently lost',async()=>{const{controller,api}=await ready();let release!:(value:Awaited<ReturnType<NotesApi['get']>>)=>void;vi.mocked(api.get).mockImplementationOnce(()=>new Promise(resolve=>{release=resolve;}));const selecting=controller.select(other);await tick();controller.editTitle('Must not change old note');expect(controller.snapshot.content?.title).toBe('Public note');release({ok:true,value:{...controller.snapshot.record!,id:other}});await selecting;expect(controller.snapshot.id).toBe(other);expect(api.write).not.toHaveBeenCalled();});
it('freezes edits once close flush is complete and close request is pending',async()=>{const{controller,api}=await ready();let release!:()=>void;vi.mocked(api.close).mockImplementationOnce(()=>new Promise<void>(resolve=>{release=resolve;}));const closing=controller.requestClose();await tick();controller.editTitle('Too late');expect(await controller.save()).toBe(true);expect(controller.snapshot.content?.title).toBe('Public note');release();expect(await closing).toBe(true);expect(api.write).not.toHaveBeenCalled();});

it('reentrant explicit close during pending publication prevents the not-yet-started write',async()=>{const{controller,api}=await ready();vi.mocked(api.close).mockRejectedValueOnce(new Error('private close failure'));controller.editTitle('Retain local');let close:Promise<boolean>|undefined;controller.subscribe(()=>{if(controller.snapshot.busy&&!controller.snapshot.closing)close=controller.closeWithoutFlush();});expect(await controller.save()).toBe(false);expect(await close).toBe(false);expect(controller.snapshot.busy).toBe(false);expect(controller.snapshot.closeFailed).toBe(true);expect(api.close).toHaveBeenCalledTimes(1);expect(api.write).not.toHaveBeenCalled();});

it('identical editor activation retains recovered draft explanation and schedules no write',async()=>{const f=fixture();controllers.push(f.controller);vi.mocked(f.api.get).mockResolvedValueOnce({ok:true,value:{...f.record,draft:content('Recovered local draft')}});await f.controller.select(id);vi.useFakeTimers();f.controller.editDocument(structuredClone(f.controller.snapshot.content!.document));f.controller.editTitle('Recovered local draft');await vi.advanceTimersByTimeAsync(600);expect(f.controller.snapshot.message).toContain('Recovered draft.');expect(f.api.write).not.toHaveBeenCalled();});

async function pinReady(){const f=await ready();f.api.setPinned=vi.fn<NonNullable<NotesApi['setPinned']>>(async input=>{Object.assign(f.record,{revision:input.expectedRevision+1,pinned:input.pinned});return{ok:true,value:structuredClone(f.record)};});f.api.list=vi.fn<NotesApi['list']>(async({query,pinnedOnly,archived,trashed})=>({ok:true,value:{query,...(trashed?{trashed:true}:{}),...(archived?{archived:true}:{}),...(pinnedOnly?{pinnedOnly:true}:{}),records:f.record.trashed===!!trashed&&(trashed||f.record.archived===!!archived)&&(!pinnedOnly||f.record.pinned)?[{id,revision:f.record.revision,title:f.record.draft.title,pinned:f.record.pinned,archived:f.record.archived,trashed:f.record.trashed,excerpt:'',hasDraft:noteContentKey(f.record.draft)!==noteContentKey(f.record.saved!),updatedAt:time}]:[],nextCursor:null}}));return f;}
it('Pin flushes newest draft, never Save, and preserves exact content/timestamps',async()=>{const f=await pinReady();f.controller.editTitle('Newest pin draft');expect(await f.controller.setPinned(true)).toBe(true);expect(f.inputs.map(input=>input.action)).toEqual(['draft']);expect(f.api.setPinned).toHaveBeenCalledExactlyOnceWith({id,expectedRevision:2,pinned:true});expect(f.controller.snapshot.record).toMatchObject({revision:3,pinned:true,draft:content('Newest pin draft'),saved:content(),createdAt:time,updatedAt:time});expect(await f.controller.setPinned(false)).toBe(true);expect(f.controller.snapshot.record?.pinned).toBe(false);});
it('pending Pin shares one request and freezes metadata/content/navigation/export/close',async()=>{const f=await pinReady();let release!:(value:Awaited<ReturnType<NonNullable<NotesApi['setPinned']>>>)=>void;vi.mocked(f.api.setPinned!).mockImplementationOnce(()=>new Promise(resolve=>{release=resolve;}));const operation=f.controller.setPinned(true);await vi.waitFor(()=>expect(f.api.setPinned).toHaveBeenCalledTimes(1));expect(f.controller.snapshot.record?.pinned).toBe(false);expect(f.controller.setPinned(false)).toBe(operation);f.controller.editTitle('Too late');f.controller.setQuery('Too late');f.controller.setPinnedOnly(true);await f.controller.newNote();await f.controller.select(other);expect(await f.controller.save()).toBe(false);expect(await f.controller.exportMarkdown()).toBe(false);expect(await f.controller.requestClose()).toBe(false);expect(await f.controller.closeWithoutFlush()).toBe(false);expect(f.api.close).not.toHaveBeenCalled();expect(f.controller.snapshot.content?.title).toBe('Public note');expect(f.controller.snapshot.query).toBe('');expect(f.controller.snapshot.pinnedOnly).toBe(false);release({ok:true,value:{...f.record,revision:2,pinned:true}});expect(await operation).toBe(true);expect(f.controller.snapshot.record?.pinned).toBe(true);});
for(const fault of ['id','revision','pinned','missing','draft','saved','createdAt','updatedAt','extra'])it(`Pin rejects ${fault} receipt and blocks until explicit fresh Reload`,async()=>{const f=await pinReady();vi.mocked(f.api.setPinned!).mockResolvedValueOnce({ok:true,value:{...f.record,id:fault==='id'?other:id,revision:fault==='revision'?99:2,pinned:fault==='pinned'?false:true,...(fault==='missing'?{pinned:undefined}:{}),...(fault==='draft'?{draft:content('Wrong')}:{}),...(fault==='saved'?{saved:null}:{}),...(fault==='createdAt'?{createdAt:'2026-10-28T00:00:00.000Z'}:{}),...(fault==='updatedAt'?{updatedAt:'2026-10-30T00:00:00.000Z'}:{}),...(fault==='extra'?{extra:true}:{})}} as never);expect(await f.controller.setPinned(true)).toBe(false);expect(f.controller.snapshot.blocked).toBe(true);expect(f.controller.snapshot.record?.pinned).toBe(false);expect(await f.controller.setPinned(true)).toBe(false);f.controller.confirmReload();await f.controller.reconcile();expect(f.controller.snapshot.blocked).toBe(false);expect(f.api.setPinned).toHaveBeenCalledTimes(1);expect(f.api.write).not.toHaveBeenCalled();});
it('known Pin refusal keeps state unchanged and permits only deliberate retry',async()=>{const f=await pinReady();vi.mocked(f.api.setPinned!).mockResolvedValueOnce({ok:false,error:{code:'capability-unavailable',message:'PRIVATE',retryable:false}});expect(await f.controller.setPinned(true)).toBe(false);expect(f.controller.snapshot.blocked).toBe(false);expect(f.controller.snapshot.record?.pinned).toBe(false);expect(f.controller.snapshot.error).not.toContain('PRIVATE');expect(await f.controller.setPinned(true)).toBe(true);expect(f.api.setPinned).toHaveBeenCalledTimes(2);});
for(const code of ['conflict','internal'] as const)it(`Pin ${code} never replays and keeps the draft until confirmed Reload`,async()=>{const f=await pinReady();vi.mocked(f.api.setPinned!).mockResolvedValueOnce({ok:false,error:{code,message:'PRIVATE',retryable:false}});expect(await f.controller.setPinned(true)).toBe(false);f.controller.editTitle('Local kept');f.controller.confirmReload();await f.controller.reconcile();expect(f.controller.snapshot.content?.title).toBe('Local kept');expect(f.controller.snapshot.blocked).toBe(false);expect(f.api.setPinned).toHaveBeenCalledTimes(1);expect(f.api.write).not.toHaveBeenCalled();});
it('Pin timeout and late acknowledgement cannot confirm or replay',async()=>{const f=await pinReady();vi.useFakeTimers();let release!:(value:Awaited<ReturnType<NonNullable<NotesApi['setPinned']>>>)=>void;vi.mocked(f.api.setPinned!).mockImplementationOnce(()=>new Promise(resolve=>{release=resolve;}));const operation=f.controller.setPinned(true);await vi.advanceTimersByTimeAsync(5001);expect(await operation).toBe(false);release({ok:true,value:{...f.record,pinned:true,revision:2}});await tick();expect(f.controller.snapshot.blocked).toBe(true);expect(f.controller.snapshot.record?.pinned).toBe(false);expect(f.api.setPinned).toHaveBeenCalledTimes(1);});
it('reentrant Pin publication disposal prevents dispatch and all late presentation',async()=>{const f=await pinReady();f.controller.subscribe(()=>{if(f.controller.snapshot.busy)f.controller.dispose();});expect(await f.controller.setPinned(true)).toBe(false);expect(f.api.setPinned).not.toHaveBeenCalled();});
it('Pin preparation rejects reentrant editing/Save/New/close before its draft flush',async()=>{const f=await pinReady();f.controller.editTitle('Latest');let close:Promise<boolean>|undefined;f.controller.subscribe(()=>{if(f.controller.snapshot.pinning&&!f.controller.snapshot.busy){f.controller.editTitle('Reentrant');void f.controller.save();void f.controller.newNote();close=f.controller.closeWithoutFlush();}});expect(await f.controller.setPinned(true)).toBe(true);expect(await close).toBe(false);expect(f.api.close).not.toHaveBeenCalled();expect(f.inputs).toHaveLength(1);expect(f.inputs[0]?.content.title).toBe('Latest');});
it('missing Pin capability, no selected note or forged argument never dispatch',async()=>{const f=await ready();expect(await f.controller.setPinned(true)).toBe(false);const fresh=fixture();controllers.push(fresh.controller);fresh.api.setPinned=vi.fn();expect(await fresh.controller.setPinned(true)).toBe(false);expect(fresh.api.setPinned).not.toHaveBeenCalled();expect(await f.controller.setPinned('yes' as never)).toBe(false);});
it('normal draft and Save cannot silently change pinned state',async()=>{const f=await pinReady();await f.controller.setPinned(true);vi.mocked(f.api.write).mockImplementationOnce(async input=>({ok:true,value:{...f.record,revision:3,pinned:false,draft:input.content,saved:input.content}}));f.controller.editTitle('Keep pin');expect(await f.controller.save()).toBe(false);expect(f.controller.snapshot.blocked).toBe(true);expect(f.controller.snapshot.record?.pinned).toBe(true);});
it('Pinned only requests owner filtering and leaves the selected editor after Unpin removes its row',async()=>{const f=await pinReady();await f.controller.setPinned(true);f.controller.setPinnedOnly(true);await vi.waitFor(()=>expect(f.controller.snapshot.rows).toHaveLength(1));expect(f.api.list).toHaveBeenLastCalledWith({query:'',pinnedOnly:true});expect(await f.controller.setPinned(false)).toBe(true);await vi.waitFor(()=>expect(f.controller.snapshot.rows).toHaveLength(0));expect(f.controller.snapshot.id).toBe(id);expect(f.controller.snapshot.content?.title).toBe('Public note');});
for(const fault of ['echo','row'] as const)it(`Pinned only rejects wrong ${fault} without publishing unfiltered rows`,async()=>{const f=await pinReady();vi.mocked(f.api.list).mockResolvedValueOnce({ok:true,value:{query:'',...(fault==='row'?{pinnedOnly:true}:{}),records:[{id,revision:1,title:'Public note',pinned:fault==='echo',archived:false,trashed:false,excerpt:'',hasDraft:false,updatedAt:time}],nextCursor:null}});f.controller.setPinnedOnly(true);await vi.waitFor(()=>expect(f.controller.snapshot.listError).toContain('could not'));expect(f.controller.snapshot.rows).toHaveLength(0);});
it('changing Pinned filter resets cursor/generation and old same-query pages cannot publish',async()=>{const f=await pinReady();vi.mocked(f.api.list).mockResolvedValueOnce({ok:true,value:{query:'',records:[{id,revision:1,title:'Public note',pinned:false,archived:false,trashed:false,excerpt:'',hasDraft:false,updatedAt:time}],nextCursor:{id,updatedAt:time}}});await f.controller.reloadList();let release!:(value:Awaited<ReturnType<NotesApi['list']>>)=>void;vi.mocked(f.api.list).mockImplementationOnce(()=>new Promise(resolve=>{release=resolve;}));const old=f.controller.reloadList(true);f.controller.setPinnedOnly(true);await vi.waitFor(()=>expect(f.controller.snapshot.listing).toBe(false));expect(f.controller.snapshot.cursor).toBeNull();expect(f.api.list).toHaveBeenLastCalledWith({query:'',pinnedOnly:true});release({ok:true,value:{query:'',records:[{id:other,revision:1,title:'Old page',pinned:false,archived:false,trashed:false,excerpt:'',hasDraft:false,updatedAt:time}],nextCursor:null}});await old;expect(f.controller.snapshot.rows).toHaveLength(0);});

it('same-turn Pin admission blocks a following selection and Close before any post-flush API',async()=>{const f=await pinReady();let release!:(value:Awaited<ReturnType<NonNullable<NotesApi['setPinned']>>>)=>void;vi.mocked(f.api.setPinned!).mockImplementationOnce(()=>new Promise(resolve=>{release=resolve;}));const pin=f.controller.setPinned(true),selection=f.controller.select(other),close=f.controller.requestClose();await vi.waitFor(()=>expect(f.api.setPinned).toHaveBeenCalledTimes(1));await selection;expect(await close).toBe(false);expect(f.api.get).toHaveBeenCalledTimes(1);expect(f.api.close).not.toHaveBeenCalled();release({ok:true,value:{...f.record,pinned:true,revision:2}});expect(await pin).toBe(true);expect(f.controller.snapshot.record?.pinned).toBe(true);expect(f.controller.snapshot.id).toBe(id);expect(f.controller.snapshot.blocked).toBe(false);});
it('Pin admitted while an earlier selection flush waits invalidates that selection without losing the pin receipt',async()=>{const f=await pinReady();let written!:(value:Awaited<ReturnType<NotesApi['write']>>)=>void,pinned!:(value:Awaited<ReturnType<NonNullable<NotesApi['setPinned']>>>)=>void;vi.mocked(f.api.write).mockImplementationOnce(()=>new Promise(resolve=>{written=resolve;}));vi.mocked(f.api.setPinned!).mockImplementationOnce(()=>new Promise(resolve=>{pinned=resolve;}));f.controller.editTitle('Flushed selection draft');const selection=f.controller.select(other),pin=f.controller.setPinned(true);await tick();Object.assign(f.record,{revision:2,draft:content('Flushed selection draft')});written({ok:true,value:structuredClone(f.record)});await vi.waitFor(()=>expect(f.api.setPinned).toHaveBeenCalledTimes(1));await selection;expect(f.api.get).toHaveBeenCalledTimes(1);expect(await f.controller.requestClose()).toBe(false);expect(f.api.close).not.toHaveBeenCalled();Object.assign(f.record,{pinned:true,revision:3});pinned({ok:true,value:structuredClone(f.record)});expect(await pin).toBe(true);expect(f.controller.snapshot.record).toMatchObject({pinned:true,revision:3,draft:content('Flushed selection draft')});expect(f.controller.snapshot.blocked).toBe(false);});
it('an earlier admitted Close prevents a same-turn Pin and does not create an unknown pin state',async()=>{const f=await pinReady();const close=f.controller.requestClose(),pin=f.controller.setPinned(true);expect(await pin).toBe(false);expect(await close).toBe(true);expect(f.api.setPinned).not.toHaveBeenCalled();expect(f.api.close).toHaveBeenCalledTimes(1);expect(f.controller.snapshot.record?.pinned).toBe(false);expect(f.controller.snapshot.blocked).toBe(false);});

